mapper.update:
update sys_role_tl
role_name = #{roleName}, role_description = #{roleDescription}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
where role_id = #{roleId} and language = #{language}

update sys_role_b
role_code = #{roleCode}, menu_id = #{menuId}, enable_flag = #{enableFlag}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
where role_id = #{roleId}

mapper.select:
select rb.role_id,rb.role_code,rb.menu_id,rb.enable_flag,
       rtl.role_name,rtl.role_description,rtl.language
from sys_role_b rb
join sys_role_tl rtl on rb.role_id = rtl.role_id and rtl.language = #{language}
join sys_user_role ur on ur.role_id = rb.role_id
where ur.user_id = #{userId}

